#!/usr/bin/env bash
set -euo pipefail

AETHERIUM_DIR="${AETHERIUM_DIR:-/opt/aetherium}"
VENV="${AETHERIUM_DIR}/venv"
LXMF_DATA="/var/lib/aetherium/lxmf"
PROPAGATION_NODE="${LXMF_PROPAGATION_NODE:-0}"

log() { echo "[lxmf/configure] $*"; }

mkdir -p "${LXMF_DATA}"

# Determine propagation mode from profile
case "${NODE_PROFILE:-}" in
    relay|mesh-hub|lte-gateway|solar-relay|emergency)
        PROPAGATION_NODE="1"
        ;;
esac

# Write lxmd config
cat > /etc/aetherium/lxmf.conf << CONF
# LXMF daemon configuration
# Generated by Aetherium

[lxmd]
  storagepath = ${LXMF_DATA}
  propagation = $([[ "${PROPAGATION_NODE}" == "1" ]] && echo True || echo False)
  announce_interval = ${LXMF_ANNOUNCE_INTERVAL:-1800}
CONF

# Write startup wrapper
cat > /opt/aetherium/venv/bin/aetherium-lxmd << 'WRAPPER'
#!/usr/bin/env bash
exec /opt/aetherium/venv/bin/python3 -m LXMF.Utilities.LXMDaemon \
    --config /etc/aetherium/lxmf.conf "$@"
WRAPPER
chmod +x /opt/aetherium/venv/bin/aetherium-lxmd

# Create systemd service if it doesn't exist in MODULE_DIR
if [[ ! -f "${MODULE_DIR}/systemd/aetherium-lxmf.service" ]]; then
    mkdir -p "${MODULE_DIR}/systemd"
    cat > "${MODULE_DIR}/systemd/aetherium-lxmf.service" << SERVICE
[Unit]
Description=LXMF Daemon
After=reticulum.service
Requires=reticulum.service

[Service]
Type=simple
User=reticulum
ExecStart=/opt/aetherium/venv/bin/python3 -m LXMF.Utilities.LXMDaemon --config /etc/aetherium/lxmf.conf
Restart=on-failure
RestartSec=15

[Install]
WantedBy=multi-user.target
SERVICE
fi

install -m644 "${MODULE_DIR}/systemd/aetherium-lxmf.service" /etc/systemd/system/ 2>/dev/null || true
systemctl daemon-reload
systemctl enable aetherium-lxmf 2>/dev/null || true
systemctl restart aetherium-lxmf || true

log "LXMF configuration complete (propagation=${PROPAGATION_NODE})"
